mapper.select:
SELECT

FROM course_detail cd
LEFT JOIN course c ON cd.course_id = c.id
LEFT JOIN user u ON cd.uploader_user_id = u.id

    cd.status = 1
    AND cd.scan_status = 'CLEAN'
    AND cd.year BETWEEN #{minYear} AND #{maxYear}

        AND cd.courseType = #{courseType}


        AND cd.course_id = #{courseId}


        AND cd.year = #{year}



        AND (
            cd.title LIKE #{keywordLike}
            OR c.course_name LIKE #{keywordLike}
            OR cd.custom_subject LIKE #{keywordLike}
            OR  LIKE #{keywordLike}
        )


ORDER BY cd.create_time DESC, cd.id DESC

mapper.update:
UPDATE course_detail
SET status = 0, update_time = NOW()
WHERE id = #{id}
  AND uploader_user_id = #{actorUserId}
  AND status = 1

UPDATE course_detail
SET status = 0, update_time = NOW()
WHERE id = #{id}
  AND status = 1
  AND EXISTS (
      SELECT 1 FROM user actor
      WHERE actor.id = #{actorUserId}
        AND actor.level = 0
  )
